const { pathToFileURL } = require("url");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const usage = { inputTokens: { total: 1, noCache: 1, cacheRead: undefined, cacheWrite: undefined }, outputTokens: { total: 1, text: 1, reasoning: undefined } };
const prompts = [];
const model = {
  specificationVersion: "v3", provider: "test", modelId: "test", supportedUrls: {},
  async doGenerate(options) {
    prompts.push(JSON.stringify(options.prompt));
    if (prompts.length === 1) return { content: [{ type: "tool-call", toolCallId: "c1", toolName: "t", input: "{}" }], finishReason: { unified: "tool-calls", raw: undefined }, usage, warnings: [] };
    return { content: [{ type: "text", text: "done" }], finishReason: { unified: "stop", raw: undefined }, usage, warnings: [] };
  },
  async doStream() { throw new Error("no stream"); },
};
(async () => {
  let ai;
  try { const m = await import(pathToFileURL(require.resolve("ai")).href); ai = m.generateText ? m : m.default; } catch (e) { broken("could not load ai: " + (e && e.message)); }
  const { generateText, tool, jsonSchema } = ai;
  try {
    await generateText({
      model,
      prompt: "ORIGINAL_PROMPT",
      tools: { t: tool({ inputSchema: jsonSchema({ type: "object", properties: {} }), execute: async () => "tool-ok" }) },
      stopWhen: ({ steps }) => steps.length >= 2,
      prepareStep: ({ stepNumber }) => stepNumber === 0 ? { messages: [{ role: "user", content: "OVERRIDE_PROMPT" }] } : undefined,
    });
  } catch (e) { broken("generateText threw: " + (e && e.message)); }
  if (prompts.length !== 2) broken("expected 2 model calls, got " + prompts.length);
  if (!prompts[0].includes("OVERRIDE_PROMPT")) broken("step 0 did not use the prepareStep messages");
  const p1 = prompts[1];
  if (!p1.includes("tool-ok")) broken("step 1 prompt lacks the tool result");
  if (p1.includes("ORIGINAL_PROMPT") && !p1.includes("OVERRIDE_PROMPT")) symptom("step 1 got the original prompt, not the prepareStep message override");
  if (!p1.includes("OVERRIDE_PROMPT") || p1.includes("ORIGINAL_PROMPT")) broken("unexpected step 1 prompt: " + p1);
  console.log("OK: the prepareStep message override carried forward to step 1");
})().catch((e) => broken("unexpected: " + (e && e.message)));

